Lemma farm_sound_0RB1LD_1RC0LA_1LD0RD_1RB1LA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_0RB1LD_1RC0LA_1LD0RD_1RB1LA r ph).
Proof.
  intros r ph H0 Hr Hph.
