Lemma ok_arm6_0RB1RB_0LC1RA_1LD0LB_1RA1LC :
  check_arm tm true true rules arm6_0RB1RB_0LC1RA_1LD0LB_1RA1LC ch_arm6_0RB1RB_0LC1RA_1LD0LB_1RA1LC = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm6_0RB1RB_0LC1RA_1LD0LB_1RA1LC : RuleSound tm true true arm6_0RB1RB_0LC1RA_1LD0LB_1RA1LC.
Proof. eapply arm_sound; [exact rules_sound_0RB1RB_0LC1RA_1LD0LB_1RA1LC | exact ok_arm6_0RB1RB_0LC1RA_1LD0LB_1RA1LC]. Qed.

