(** 0RB1RD_1LC0RA_1RA1LB_0LC1RA *)
Definition tm_0RB1RD_1LC0RA_1RA1LB_0LC1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB
  | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DL StC
  | StB, S1 => mk S0 DR StA
  | StC, S0 => mk S1 DR StA
  | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DL StC
  | StD, S1 => mk S1 DR StA
  end.
