Lemma farm_sound_1RB0LA_1LC0LC_1RD1LB_1LA0RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB0LA_1LC0LC_1RD1LB_1LA0RD r ph).
