Import LadderCheckLiftTr.
Import ListNotations.

Definition mk_1RB0LA_1LC0RD_1LA1LB_0LC1RD (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB0LA_1LC0RD_1LA1LB_0LC1RD.

(** 1RB0LA_1LC0RD_1LA1LB_0LC1RD *)
Definition tm_1RB0LA_1LC0RD_1LA1LB_0LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S0 DL StA
  | StB, S0 => mk S1 DL StC
  | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DL StA
  | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DL StC
  | StD, S1 => mk S1 DR StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0LA_1LC0RD_1LA1LB_0LC1RD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0LA_1LC0RD_1LA1LB_0LC1RD pins_1RB0LA_1LC0RD_1LA1LB_0LC1RD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LA_1LC0RD_1LA1LB_0LC1RD : Fam := mkFam 2 [[S1;S1];[S1;S0]] [] [[S0;S1]] Binary 1 [mkFill 2 [] 0 [] 0] StD S0 true [].
Local Notation FAM := fam_1RB0LA_1LC0RD_1LA1LB_0LC1RD.

(** ** The ladder, as DATA

    5 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LA_1LC0RD_1LA1LB_0LC1RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StB (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB0LA_1LC0RD_1LA1LB_0LC1RD.

Definition rules_1RB0LA_1LC0RD_1LA1LB_0LC1RD : list LRule := map fst lad.
Local Notation rules := rules_1RB0LA_1LC0RD_1LA1LB_0LC1RD.

Lemma ladder_ok_1RB0LA_1LC0RD_1LA1LB_0LC1RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LA_1LC0RD_1LA1LB_0LC1RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LA_1LC0RD_1LA1LB_0LC1RD. Qed.

