          (mkC StD (mkS [S0;S0] [S0;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 [])) 4 6.
Definition ch_iarm0_1_1RB0LA_1LC1LA_1RD1LB_0LC0RD : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWin 2);RB (SCycR 2);RB (SWin 2)].
Lemma ok_iarm0_1_1RB0LA_1LC1LA_1RD1LB_0LC0RD :
