Definition iarm_1RB0LA_1LC1LA_1RD1LB_0LC0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LA_1LC1LA_1RD1LB_0LC0RD
  | 0, 1 => iarm0_1_1RB0LA_1LC1LA_1RD1LB_0LC0RD
  | _, _ => iarm0_0_1RB0LA_1LC1LA_1RD1LB_0LC0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

