Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LA_1LC1LA_1RD1LB_0LC0RD | exact ok_iarm0_0_1RB0LA_1LC1LA_1RD1LB_0LC0RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LA_1LC1LA_1RD1LB_0LC0RD | exact ok_iarm0_1_1RB0LA_1LC1LA_1RD1LB_0LC0RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

