          (mkC StD (mkS [S0;S0;S0] [S0;S0;S0] 1 0 [S1;S0;S0]) S0 (mkS [] [] 0 0 [])) 8 10.
Definition ch_iarm0_1_1RB0LA_1LC1LB_1RD1LA_0LC0RD : list rstep := [RB (SWin 5);RB (SCycL 5 0);RB (SWin 2);RB (SCycR 3);RB (SWin 3)].
