    { eapply arm_sound; [exact rules_sound_1RB0LA_1LC1LB_1RD1LA_0LC0RD | exact ok_iarm0_0_1RB0LA_1LC1LB_1RD1LA_0LC0RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LA_1LC1LB_1RD1LA_0LC0RD | exact ok_iarm0_1_1RB0LA_1LC1LB_1RD1LA_0LC0RD]. }
    exfalso; lia.
