  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S0] [S0;S1;S0] 1 0 [S0;S1]))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S1;S1;S0;S0;S1])) 8 20.
