    { eapply arm_sound; [exact rules_sound_1RB0LC_1LA0RD_0RA1LD_1RA1LC | exact ok_iarm0_0_1RB0LC_1LA0RD_0RA1LD_1RA1LC]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LC_1LA0RD_0RA1LD_1RA1LC | exact ok_iarm0_1_1RB0LC_1LA0RD_0RA1LD_1RA1LC]. }
    exfalso; lia.
