Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LC_1LA0RD_1LB1RD_0LB1RC (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_1LA0RD_1LB1RD_0LB1RC
  | 0, 1 => iarm0_1_1RB0LC_1LA0RD_1LB1RD_0LB1RC
  | _, _ => iarm0_0_1RB0LC_1LA0RD_1LB1RD_0LB1RC   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB0LC_1LA0RD_1LB1RD_0LB1RC : LRule :=
  mkLRule (mkC StD (mkS [S0;S1;S0] [S0;S1;S0] 1 0 [S0;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S1;S1;S0;S0;S1]) S0 (mkS [] [] 0 0 [])) 8 20.
