Lemma farm_rhs_1RB0LC_1LA1RC_1RA0LD_0RB1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB0LC_1LA1RC_1RA0LD_0RB1LD r ph)
