    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB____0LC0RB_0LD1LC_1RA1RA | exact ok_iarm0_1_1RB____0LC0RB_0LD1LC_1RA1RA]. }
    exfalso; lia.
